#include "kernel.hpp"
int main(int argc,char**argv){try{need(argc==5,"p exponent data output");int p=std::stoi(argv[1]),e=std::stoi(argv[2]);init(p,0,0,e,std::string(argv[3])+"/log_table.txt");std::vector<I>c(NL,K/Q),x(NL),y(NL);for(int i=0;i<NL;i++){x[i]=I(K/Q)*((I(i)*i+17*i+13)%101-50);y[i]=I(K/Q)*((i%7)-3);}tensor(c);tensor(x);tensor(y);std::ofstream out(argv[4]);need(bool(out),"algebra output");for(int i=0;i<NL;i++){need(c[i]==K,"all branches normalize to one");out<<i<<" "<<c[i]<<" "<<x[i]<<" "<<y[i]<<"\n";}need(bool(out),"algebra output complete");std::cout<<"PASS algebra Q="<<Q<<" K="<<K<<" labels="<<NL<<"\n";}catch(std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 2;}}
